// User uploaded background image (Screenshot 2026-09-29 111537.png)
export const USER_BACKGROUND_IMAGE = "data:image/png;base64,";

export function applyUserBackground() {
  if (typeof document === "undefined") return;
  const s = document.documentElement.style;
  s.setProperty("--user-bg-image", `url("data:image/png;base64,")`);
  s.setProperty("--pixel-sky", `url("data:image/png;base64,")`);
  s.setProperty("--pixel-clouds", "none");
}
